@test
def test_studentized_range():
    sr_ = st.studentized_range
    out = [sr_.cdf(3.5, 4.0, 10.0), sr_.sf(3.5, 4.0, 10.0), sr_.pdf(3.5, 4.0, 10.0),
           sr_.cdf(2.0, 3.0, 200000.0), sr_.ppf(0.9, 4.0, 10.0)]
    assert close(out, sr, 1e-9, 1e-10)

@test
def test_tukey():
    r = st.tukey_hsd(g1, g2, g3)
    assert close(r.statistic, th_s, 1e-9, 1e-10)
    assert close(r.pvalue, th_p, 1e-8, 1e-10)
    ci = r.confidence_interval(0.9)
    assert close(ci.low, th_lo, 1e-8, 1e-9)
    assert close(ci.high, th_hi, 1e-8, 1e-9)
    r = st.tukey_hsd(g1, g2, g3, equal_var=False)
    assert close(r.pvalue, thw_p, 1e-8, 1e-10)
    assert close(r.confidence_interval().low, thw_lo, 1e-8, 1e-9)

@test
def test_dunnett_mvt():
    out = []
    for alt in ['two-sided', 'less', 'greater']:
        r = st.dunnett(g1, g2, g3, control=ctl, alternative=alt, rng=7)
        out += list(r.statistic) + list(r.pvalue)
    assert close(out, dn, 2e-3, 1e-4)
    r = st.dunnett(g1, g2, g3, control=ctl, rng=7)
    ci = r.confidence_interval()
    assert close(ci.low, dn_lo, 1e-3, 1e-3)
    assert close(ci.high, dn_hi, 1e-3, 1e-3)
    rho = np.array([[1., .5, .2], [.5, 1., .3], [.2, .3, 1.]])
    m = st.multivariate_t(shape=rho, df=5.0)
    a = m.cdf(np.array([1.0, 0.5, 2.0]), random_state=3)
    b = m.cdf(np.array([1.0, 0.5, 2.0]), lower_limit=np.array([-1., -2., -0.5]), random_state=3)
    assert close([a, b], mvt, 1e-3, 1e-5)

test_studentized_range()
test_tukey()
test_dunnett_mvt()
